def fill_positions(apps, schema_editor):
    """Порядок книги для старых партий: порядок создания строк.

    Строки Зива, выделенные из слипшихся задач, досоздавались в конце
    партии; ставим их сразу за ближайшей предшественницей по номеру.
    """
